//! Stories: the ACL in front of the commands. The ACL is the real one, built from
//! `permissions/default.toml` and the autogenerated command permissions.
#![cfg(not(any(target_os = "android", target_os = "ios")))]

mod common;
use common::*;

/// Given an app granted `widgets:default`,
/// When it invokes every command the plugin registers,
/// Then none is refused by the ACL (`{}` is invalid for most commands: any answer but an
/// ACL denial proves the gate opened).
#[test]
fn default_permission_allows_every_command() {
    let app = App::new();
    for name in command_names() {
        if let Err(e) = app.call(&name, json!({})) {
            assert!(!is_acl_denial(&e), "{name} denied by widgets:default: {e}");
        }
    }
}

/// Given an app granted only `widgets:allow-get-items`,
/// When it calls `set_items` and `get_items`,
/// Then the write is denied by the ACL and the read is answered.
#[test]
fn commands_denied_without_permission() {
    let app = App::with_permissions(&["widgets:allow-get-items"]);
    let e = app
        .call("set_items", json!({ "key": "k", "value": "v" }))
        .unwrap_err();
    assert!(is_acl_denial(&e), "{e}");
    assert!(app.call("get_items", json!({ "key": "k" })).is_ok());
}
